WHERE details_json IS NOT NULL AND json_valid(details_json) AND json_extract(details_json, '$.recapModel') IN ('kimi-k2.6-fireworks','deepseek-v4-flash','mimo-v2.5-pro','mimo-v2.5','gpt-5.3-codex-spark-codex-bridge','gpt-5.5-codex-bridge');
